require "uri"

module DocIntake
  module Part2
    # Resolves the URL a borrower is sent to when downloading a finished
    # pack. Packs are served from the document CDN; links are generated by
    # the archiver and round-trip through the portal as a query parameter so
    # that the portal can record the download before handing off.
    module DownloadLocation
      DEFAULT_CDN_HOST = "docs-cdn.lending.internal.test".freeze
      FALLBACK_PATH = "/portal/packs".freeze

      module_function

      def cdn_host
        ENV.fetch("DOC_INTAKE_CDN_HOST", DEFAULT_CDN_HOST)
      end

      # Returns a URL that is guaranteed to point at the CDN over https, or
      # the portal's own pack list when the supplied value is anything else.
      # Relative CDN paths are expanded against the CDN host.
      def for(candidate)
        raw = candidate.to_s.strip
        return FALLBACK_PATH if raw.empty? || raw.include?("\\") || raw.match?(/[\r\n]/)

        uri = URI.parse(raw)
        return cdn_url(uri.path, uri.query) if uri.relative? && uri.host.nil? && raw.start_with?("/packs/")
        return FALLBACK_PATH unless uri.is_a?(URI::HTTPS)
        return FALLBACK_PATH unless uri.host&.casecmp?(cdn_host)
        return FALLBACK_PATH unless uri.userinfo.nil? && [nil, 443].include?(uri.port)

        uri.to_s
      rescue URI::InvalidURIError
        FALLBACK_PATH
      end

      def cdn_url(path, query = nil)
        URI::HTTPS.build(host: cdn_host, path: path, query: query).to_s
      end
    end
  end
end
